// Guards: Provider Description mandate §8: fail closed on production contract drift, including exact per-signature EXECUTE grants.
import assert from 'node:assert/strict'
import fs from 'node:fs'
import {sql,quote} from './db.mjs'
const root='tests/fixtures/provider-description-autonomy/'
const m=JSON.parse(fs.readFileSync(root+'production-metadata.json'))
const p=JSON.parse(fs.readFileSync(root+'production-parity.json'))
const funcs=JSON.parse(fs.readFileSync(root+'function-signatures.json'))
const grants=JSON.parse(fs.readFileSync(root+'production-exact-function-grants.json'))
const names=[...new Set([...m.columns.map(c=>c.table_schema+'.'+c.table_name),...p.constraints.map(c=>c.relation),...p.triggers.map(t=>t.relation)])]
const snapshot=sql(`select jsonb_build_object('columns',(select jsonb_agg(to_jsonb(c)) from (select table_schema,table_name,column_name,udt_name,is_nullable,column_default from information_schema.columns where table_schema||'.'||table_name=any(array[${names.map(quote).join(',')}]))c),'constraints',(select jsonb_agg(jsonb_build_object('relation',conrelid::regclass::text,'name',conname,'definition',pg_get_constraintdef(oid,true))) from pg_constraint where conrelid::regclass::text=any(array[${names.map(quote).join(',')}])),'triggers',(select jsonb_agg(jsonb_build_object('relation',tgrelid::regclass::text,'name',tgname,'definition',pg_get_triggerdef(oid,true))) from pg_trigger where not tgisinternal and tgrelid::regclass::text=any(array[${names.map(quote).join(',')}])),'functions',(select jsonb_agg(jsonb_build_object('signature',sig,'md5',md5(pg_get_functiondef(sig::regprocedure)),'anon',has_function_privilege('anon',sig,'EXECUTE'),'authenticated',has_function_privilege('authenticated',sig,'EXECUTE'),'service_role',has_function_privilege('service_role',sig,'EXECUTE'))) from unnest(array[${funcs.map(f=>quote(f.signature)).join(',')}])sig));`,{role:'postgres',json:true})
for(const c of m.columns){const actual=snapshot.columns.find(a=>a.table_schema===c.table_schema&&a.table_name===c.table_name&&a.column_name===c.column_name);assert.ok(actual,'missing production column '+c.column_name);for(const key of ['udt_name','is_nullable','column_default'])assert.equal(actual[key],c[key],`${c.table_name}.${c.column_name} ${key}`)}
for(const c of p.constraints){const actual=snapshot.constraints.find(a=>a.relation===c.relation&&a.name===c.conname);assert.equal(actual?.definition,c.definition,'production constraint drift '+c.conname)}
for(const t of p.triggers){const actual=snapshot.triggers.find(a=>a.relation===t.relation&&a.name===t.tgname);assert.equal(actual?.definition,t.definition,'production trigger drift '+t.tgname)}
const canonical=s=>s.replace(/\s*,\s*/g,',').replace(/\s+/g,' ').trim()
for(const f of funcs){const actual=snapshot.functions.find(a=>a.signature===f.signature);assert.equal(actual.md5,f.md5,'production function body drift '+f.signature);for(const role of ['anon','authenticated','service_role']){const expected=grants.some(g=>canonical(g.signature)===canonical(f.signature)&&[role,'PUBLIC'].includes(g.grantee));assert.equal(actual[role],expected,`${f.signature} ${role} EXECUTE drift`)}}
const zoho=JSON.parse(fs.readFileSync(root+'production-zoho.json'))
const zohoGrants=JSON.parse(fs.readFileSync(root+'production-zoho-grants.json')).functions
const z=sql(`select jsonb_agg(jsonb_build_object('signature',sig,'md5',md5(pg_get_functiondef(sig::regprocedure)),'anon',has_function_privilege('anon',sig,'EXECUTE'),'authenticated',has_function_privilege('authenticated',sig,'EXECUTE'),'service_role',has_function_privilege('service_role',sig,'EXECUTE'))) from unnest(array[${zoho.functions.map(f=>quote(f.signature)).join(',')}])sig;`,{role:'postgres',json:true})
for(const f of zoho.functions){const actual=z.find(x=>x.signature===f.signature);assert.equal(actual.md5,f.md5,'actual Zoho/cache function hash '+f.signature);const acl=zohoGrants.find(x=>x.signature===f.signature);for(const role of ['anon','authenticated','service_role'])assert.equal(actual[role],acl.grants.some(g=>[role,'PUBLIC'].includes(g.grantee)),f.signature+' '+role+' grant')}
console.log('PASS six unchanged real Zoho/cache function hashes and exact signature grants')
fs.mkdirSync('docs/ui-evidence',{recursive:true});fs.writeFileSync('docs/ui-evidence/provider-description-schema-parity.json',JSON.stringify({captured_production:'2026-11-04',schema_only:true,columns_checked:m.columns.length,constraints_checked:p.constraints.length,triggers_checked:p.triggers.length,functions_checked:funcs.length,zoho_functions_checked:zoho.functions.length,postgres_settings:JSON.parse(fs.readFileSync(root+'production-postgres-settings.json')),parity:'PASS'},null,2)+'\n')
console.log(`PASS production parity: ${m.columns.length} columns, ${p.constraints.length} constraints, ${p.triggers.length} triggers, ${funcs.length} function hashes and exact signature grants`)
